// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.traceimport com.roshan.persona.brain.context.SessionIdimport com.roshan.persona.brain.skill.SkillOutputimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport java.time.Instant/** * NOUS — Brain trace (audit log entry for one full brain request). * * Every request produces a BrainTrace — a complete decision tree of what * happened at each layer. Skipped layers are recorded with [LayerDecision.SKIP] * and a [LayerTrace.skipReason]. The trace is: *   - Persisted to Room `brain_traces` table with 90-day retention *   - User-accessible in Settings → Privacy → Audit Log → Brain Traces *   - Exportable (encrypted ZIP) *   - Never synced to cloud (privacy) * * @see <a href="docs/spec/module2-spec-review.pdf">§8.1 BrainTrace</a> */data class BrainTrace(    /** Correlation ID — joins all layers of one request. */    val correlationId: CorrelationId,    /** Conversation session ID. */    val sessionId: SessionId,    /** User input with PII scrubbed (never raw). */    val inputRedacted: String,    /** Request start time (UTC). */    val startedAt: Instant,    /** Request end time (UTC). */    val completedAt: Instant,    /** Total wall-clock duration in milliseconds. */    val totalDurationMs: Long,    /** Per-layer trace entries (Layer 0 through Layer 5). */    val layers: List<LayerTrace>,    /** Final skill output (if any). */    val finalOutput: SkillOutput?,    /** Final error (if request failed). */    val finalError: AppError?,    /** Total LLM cost in USD (if cloud LLM was used). */    val totalCostUsd: Float,    /** Total LLM tokens generated. */    val totalTokensGenerated: Int,) {    /** Whether the request succeeded. */    val isSuccess: Boolean        get() = finalError == null && finalOutput is SkillOutput.Success    /** Whether the request was partial (completed with warnings). */    val isPartial: Boolean        get() = finalOutput is SkillOutput.Partial    /** Layer trace summary for debugging UI. */    fun layerSummary(): String = layers.joinToString(" → ") { layer ->        val short = layer.layer.shortName        when (layer.decision) {            LayerDecision.PROCEED -> "$short ✓"            LayerDecision.DEFER -> "$short →"            LayerDecision.FAIL -> "$short ✗"            LayerDecision.SKIP -> "$short ⊘"        }    }}/** * One layer's trace entry. */data class LayerTrace(    /** Which layer (0-5). */    val layer: Layer,    /** When this layer was entered. */    val enteredAt: Instant,    /** When this layer exited (null = never entered). */    val exitedAt: Instant?,    /** Wall-clock duration (null if never entered). */    val durationMs: Long?,    /** What happened at this layer. */    val decision: LayerDecision,    /** Why this layer was skipped (null if entered). */    val skipReason: String?,    /** Output produced (Intent for L0, BrainRule for L1, SkillOutput for L2+). */    val output: Any?,    /** Error (if decision = FAIL). */    val error: AppError?,)/** * Brain layers. */enum class Layer(val number: Int, val shortName: String, val displayName: String) {    INTENT(0, "L0", "IntentClassifier"),    RULE(1, "L1", "RuleEngine"),    SKILL(2, "L2", "SkillRouter"),    LOCAL_LLM(3, "L3", "LocalLLM"),    CLOUD_LLM(4, "L4", "CloudLLM"),    AGENTIC(5, "L5", "AgenticOrchestrator");    companion object {        fun fromNumber(number: Int): Layer = entries.first { it.number == number }    }}/** * Layer decision — what happened at a layer. */enum class LayerDecision {    /** Layer executed and produced an output. */    PROCEED,    /** Layer executed but deferred to next layer. */    DEFER,    /** Layer failed (error). */    FAIL,    /** Layer was skipped (never entered, e.g., earlier layer handled it). */    SKIP,}